1|import "server-only";
2|import { timingSafeEqual } from "node:crypto";
3|import type { KV } from "@/core/types";
4|import { UPLOAD_TTL_DAYS, isUploadId } from "@/core/uploads";
5|import { usable } from "@/server/guard/env";
6|import { createRestKV } from "@/server/guard/kv";
7|import { createUploadStore, type UploadStore } from "./blob";
8|import { failUploadJob, loadUploadJob } from "./state";
9|
10|// Jobs still working past this hold a reserve for work that will never
11|// land; the daily cron settles them to their recorded usage and fails them.
12|export const UPLOAD_STALE_MS = 6 * 3600 * 1000;
13|
14|// Settles stale working jobs discovered through their blobs. Exactly once
15|// per job via the settle guard, so a retry never double-adjusts.
16|async function reconcileStaleJobs(kv: KV, store: UploadStore, paths: string[], nowMs: number): Promise<number> {
17|  const ids = new Set<string>();
18|  for (const path of paths) {
19|    const id = path.split("/")[1];
20|    if (id && isUploadId(id)) ids.add(id);
21|  }
22|  let reconciled = 0;
23|  for (const id of ids) {
24|    let job;
25|    try {
26|      job = await loadUploadJob(kv, id);
27|    } catch {
28|      continue;
29|    }
30|    if (!job || job.status !== "working" || job.reservedMicro <= 0) continue;
31|    if (nowMs - job.createdAt <= UPLOAD_STALE_MS) continue;
32|    await failUploadJob(kv, store, job);
33|    reconciled += 1;
34|  }
35|  return reconciled;
36|}
37|
38|// Deletes upload blobs older than the TTL and settles stale working jobs
39|// to their recorded usage. Job state in Redis expires on its own; only
40|// Blob needs sweeping. One failure never stops the rest.
41|export async function cleanupUploads(
42|  store: UploadStore,
43|  nowMs: number = Date.now(),
44|  deps: { kv?: KV } = {},
45|): Promise<{ deleted: number; reconciled: number }> {
46|  const cutoff = nowMs - UPLOAD_TTL_DAYS * 24 * 3600 * 1000;
47|  const blobs = await store.listAll("uploads/");
48|  let deleted = 0;
49|  for (const blob of blobs) {
50|    if (blob.uploadedAt >= cutoff) continue;
51|    try {
52|      await store.remove(blob.pathname);
53|      deleted += 1;
54|    } catch {
55|      // The next daily run retries.
56|    }
57|  }
58|  const reconciled = deps.kv ? await reconcileStaleJobs(deps.kv, store, blobs.map((b) => b.pathname), nowMs) : 0;
59|  return { deleted, reconciled };
60|}
61|
62|function matchesBearer(auth: string, secret: string): boolean {
63|  const expected = `Bearer ${secret}`;
64|  if (auth.length !== expected.length) return false;
65|  return timingSafeEqual(Buffer.from(auth), Buffer.from(expected));
66|}
67|
68|// Vercel cron calls this daily with CRON_SECRET as the Bearer [REDACTED] Any
69|// auth failure answers 404 so the route stays hidden.
70|export async function handleCleanup(
71|  req: Request,
72|  deps: { store?: UploadStore; secret?: string; token?: string; kv?: KV } = {},
73|): Promise<Response> {
74|  const secret = deps.secret ?? usable(process.env.CRON_SECRET);
75|  if (!secret || !matchesBearer(req.headers.get("authorization") ?? "", secret)) {
76|    return Response.json({ status: "error", code: "not_found" }, { status: 404 });
77|  }
78|  // Same private store as the routes; never the public image store.
79|  const token = deps.token ?? usable(process.env.UPLOADS_BLOB_READ_WRITE_TOKEN);
80|  if (!deps.store && !token) {
81|    console.warn("upload cleanup unavailable");
82|    return Response.json({ status: "error", code: "unavailable" }, { status: 503 });
83|  }
84|  let kv = deps.kv;
85|  if (!kv) {
86|    const url = usable(process.env.UPSTASH_REDIS_REST_URL) ?? usable(process.env.KV_REST_API_URL);
87|    const kvToken = usable(process.env.UPSTASH_REDIS_REST_TOKEN) ?? usable(process.env.KV_REST_API_TOKEN);
88|    if (url?.startsWith("https://") && kvToken) kv = createRestKV(url, kvToken);
89|    // Without Redis the cron still sweeps blobs and skips the reconcile.
90|  }
91|  try {
92|    const out = await cleanupUploads(deps.store ?? createUploadStore(token as string), Date.now(), kv ? { kv } : {});
93|    return Response.json({ status: "ok", deleted: out.deleted });
94|  } catch {
95|    console.error("upload cleanup failed");
96|    return Response.json({ status: "error", code: "unavailable" }, { status: 503 });
97|  }
98|}

