1|import "server-only";
2|import type { KV } from "@/core/types";
3|import {
4|  UPLOAD_JOB_TTL_SEC,
5|  isUploadId,
6|  partKey,
7|  uploadDailySpendKey,
8|  uploadPartPath,
9|  type UploadErrorCode,
10|  type UploadPart,
11|} from "@/core/uploads";
12|import { refundDualQuota } from "@/server/guard/quota";
13|import { spendKey } from "@/server/guard/spend";
14|import { jevCostUsd, metaCostUsd } from "../../pipeline/prices";
15|import type { UploadStore } from "./blob";
16|
17|// Control flow between orchestration and HTTP: the handler maps the code
18|// to a status and message, never the wrapped error.
19|export class UploadFailure extends Error {
20|  constructor(public code: UploadErrorCode) {
21|    super(code);
22|    this.name = "UploadFailure";
23|  }
24|}
25|
26|// Job state lives in Redis; book text lives in private Blob. The state
27|// holds ordinals and money only, never text and never keys.
28|export interface UploadUsage {
29|  metaPrompt: number;
30|  metaCached: number;
31|  metaCompletion: number;
32|  metaRequests: number;
33|  jevInput: number;
34|  jevOutput: number;
35|  jevRequests: number;
36|}
37|
38|export function emptyUsage(): UploadUsage {
39|  return { metaPrompt: 0, metaCached: 0, metaCompletion: 0, metaRequests: 0, jevInput: 0, jevOutput: 0, jevRequests: 0 };
40|}
41|
42|// Steps never mutate the job's usage (parallel drivers would lose each
43|// other's counts); each part result carries its own usage and the terminal
44|// paths sum job usage plus every finished part.
45|export function sumUsage(all: UploadUsage[]): UploadUsage {
46|  const total = emptyUsage();
47|  for (const usage of all) {
48|    total.metaPrompt += usage.metaPrompt;
49|    total.metaCached += usage.metaCached;
50|    total.metaCompletion += usage.metaCompletion;
51|    total.metaRequests += usage.metaRequests;
52|    total.jevInput += usage.jevInput;
53|    total.jevOutput += usage.jevOutput;
54|    total.jevRequests += usage.jevRequests;
55|  }
56|  return total;
57|}
58|
59|export function isUsageZero(usage: UploadUsage): boolean {
60|  return (
61|    usage.metaPrompt === 0 &&
62|    usage.metaCached === 0 &&
63|    usage.metaCompletion === 0 &&
64|    usage.metaRequests === 0 &&
65|    usage.jevInput === 0 &&
66|    usage.jevOutput === 0 &&
67|    usage.jevRequests === 0
68|  );
69|}
70|
71|export function usageCostMicro(usage: UploadUsage): number {
72|  const usd =
73|    metaCostUsd({ prompt: usage.metaPrompt, cached: usage.metaCached, completion: usage.metaCompletion }) +
74|    jevCostUsd(usage.jevInput);
75|  return Math.round(usd * 1_000_000);
76|}
77|
78|export function usageCostUsd(usage: UploadUsage): number {
79|  return Math.round((usageCostMicro(usage) / 1_000_000) * 1_000_000) / 1_000_000;
80|}
