91|export interface UploadJob {
92|  v: 1;
93|  id: string;
94|  path: "free" | "byok";
95|  anonId: string | null;
96|  day: string;
97|  createdAt: number;
98|  title: string;
99|  author: string;
100|  textVersion: string;
101|  chapters: UploadJobChapter[];
102|  parts: UploadPart[];
103|  doneParts: string[];
104|  status: UploadStatus;
105|  usage: UploadUsage;
106|  reservedMicro: number;
107|  quotaIp: string | null;
108|  quotaAnon: string | null;
109|  costMicro: number | null;
110|}
