116|export function uploadLockKey(id: string, part: string): string {
117|  return `upload:lock:${id}:${part}`;
118|}
119|
120|// Guards the exactly-once refund and finalize across concurrent drivers.
121|export function uploadRefundKey(id: string): string {
122|  return `upload:refunded:${id}`;
123|}
124|
125|export function uploadFinalizeKey(id: string): string {
126|  return `upload:finalized:${id}`;
127|}
128|
129|export const UPLOAD_LOCK_TTL_SEC = 120;
130|// Short lease, not a durable marker: a finalize killed at the 60 s limit
131|// frees the key, and the settle guard below still keeps spend exactly-once.
132|export const UPLOAD_FINALIZE_LEASE_SEC = 90;
