134|function isPart(value: unknown): value is UploadPart {
135|  if (typeof value !== "object" || value === null) return false;
136|  const p = value as Record<string, unknown>;
137|  return (
138|    Number.isSafeInteger(p.ch) &&
139|    (p.ch as number) >= 1 &&
140|    Number.isSafeInteger(p.part) &&
141|    (p.part as number) >= 1 &&
142|    Number.isSafeInteger(p.startN) &&
143|    Number.isSafeInteger(p.endN) &&
144|    (p.startN as number) <= (p.endN as number)
145|  );
146|}
147|
148|export function isUsage(value: unknown): value is UploadUsage {
149|  if (typeof value !== "object" || value === null) return false;
150|  return (["metaPrompt", "metaCached", "metaCompletion", "metaRequests", "jevInput", "jevOutput", "jevRequests"] as const).every(
151|    (k) => typeof (value as Record<string, unknown>)[k] === "number",
152|  );
153|}
154|
155|// Defensive read: Redis is trusted but a corrupt value must not crash the
156|// route. Returns the job, or null when missing or unparseable.
157|export function parseUploadJob(raw: string | null): UploadJob | null {
158|  if (raw === null) return null;
159|  let json: unknown;
160|  try {
161|    json = JSON.parse(raw);
162|  } catch {
163|    return null;
164|  }
165|  if (typeof json !== "object" || json === null) return null;
166|  const j = json as Record<string, unknown>;
167|  if (j.v !== 1 || !isUploadId(j.id)) return null;
168|  if (j.path !== "free" && j.path !== "byok") return null;
169|  if (j.anonId !== null && typeof j.anonId !== "string") return null;
170|  if (typeof j.day !== "string" || typeof j.createdAt !== "number") return null;
171|  if (typeof j.title !== "string" || typeof j.author !== "string") return null;
172|  if (typeof j.textVersion !== "string") return null;
173|  if (!Array.isArray(j.chapters) || !Array.isArray(j.parts) || !Array.isArray(j.doneParts)) return null;
174|  if (!j.parts.every(isPart) || !j.doneParts.every((d) => typeof d === "string")) return null;
175|  if (j.status !== "working" && j.status !== "done" && j.status !== "failed") return null;
176|  if (!isUsage(j.usage)) return null;
177|  if (typeof j.reservedMicro !== "number") return null;
178|  if (j.quotaIp !== null && typeof j.quotaIp !== "string") return null;
179|  if (j.quotaAnon !== null && typeof j.quotaAnon !== "string") return null;
180|  if (j.costMicro !== null && typeof j.costMicro !== "number") return null;
181|  for (const c of j.chapters) {
182|    if (typeof c !== "object" || c === null) return null;
183|    const ch = c as Record<string, unknown>;
184|    if (!Number.isSafeInteger(ch.ch) || typeof ch.title !== "string") return null;
185|    if (!Number.isSafeInteger(ch.start_n) || !Number.isSafeInteger(ch.end_n)) return null;
186|  }
187|  return json as UploadJob;
188|}
189|
190|export async function loadUploadJob(kv: KV, id: string): Promise<UploadJob | null> {
191|  return parseUploadJob(await kv.get(uploadJobKey(id)));
192|}
193|
194|export async function saveUploadJob(kv: KV, job: UploadJob): Promise<void> {
195|  await kv.set(uploadJobKey(job.id), JSON.stringify(job));
196|  await kv.expire(uploadJobKey(job.id), UPLOAD_JOB_TTL_SEC);
197|}
198|
199|function parsePartUsage(raw: string | null): UploadUsage {
200|  if (raw === null) return emptyUsage();
201|  try {
202|    const json: unknown = JSON.parse(raw);
203|    if (typeof json === "object" && json !== null && isUsage((json as { usage?: unknown }).usage)) {
204|      return (json as { usage: UploadUsage }).usage;
205|    }
206|  } catch {
207|    // A corrupt part counts as empty here; finalize still validates scenes.
208|  }
209|  return emptyUsage();
210|}
211|
212|// Every terminal path tallies the same way: create-time judge usage plus
213|// each finished part's blob usage, plus the failing step's in-flight usage
214|// when the caller hands it over. Blobs without a usage field count as
215|// empty, so jobs straddling the deploy still tally exactly once.
216|export async function sumRecordedUsage(store: UploadStore, job: UploadJob, extra?: UploadUsage): Promise<UploadUsage> {
217|  const parts: UploadUsage[] = [];
218|  for (const p of job.parts) {
219|    parts.push(parsePartUsage(await store.readText(uploadPartPath(job.id, partKey(p)))));
220|  }
221|  return sumUsage(extra ? [job.usage, extra, ...parts] : [job.usage, ...parts]);
222|}
223|
224|// The only money writer. The first caller folds actual-minus-reserved into
225|// both spend counters; every other terminal path is a no-op, so a retried
226|// finalize, a racing fail, and the stale cleanup can never double-adjust.
227|// Never throws; true when this call won the guard.
228|export async function settleSpendOnce(kv: KV, job: UploadJob, actualMicro: number): Promise<boolean> {
229|  let first = false;
230|  try {
231|    first = await kv.setNxEx(uploadRefundKey(job.id), "1", UPLOAD_JOB_TTL_SEC);
232|  } catch {
233|    return false;
234|  }
235|  if (!first || job.reservedMicro <= 0) return first;
236|  const delta = actualMicro - job.reservedMicro;
237|  if (delta !== 0) {
238|    try {
239|      await kv.incrBy(spendKey(), delta);
240|      await kv.incrBy(uploadDailySpendKey(job.day), delta);
241|    } catch {
242|      // Kept on Redis failure: conservative, like an abandoned job.
243|    }
244|  }
245|  return true;
246|}
247|
248|// Marks the job failed, keeps what was really spent, and refunds the book
249|// quota only when nothing ran at all. Exactly once via the settle guard,
250|// best effort throughout: when the tally itself fails the reserve is kept,
251|// which is the conservative side. A job already done is never touched.
252|export async function failUploadJob(kv: KV, store: UploadStore, job: UploadJob, extra?: UploadUsage): Promise<void> {
253|  if (job.status === "done") return;
254|  let usage: UploadUsage | null = null;
255|  try {
256|    usage = await sumRecordedUsage(store, job, extra);
257|  } catch {
258|    usage = null;
259|  }
260|  job.status = "failed";
261|  if (usage) job.usage = usage;
262|  try {
263|    await saveUploadJob(kv, job);
264|  } catch {
265|    // The settle guard below still bounds us to one money write.
266|  }
267|  const first = await settleSpendOnce(kv, job, usage ? usageCostMicro(usage) : job.reservedMicro);
268|  if (first && usage && isUsageZero(usage) && job.quotaIp && job.quotaAnon) {
269|    await refundDualQuota(kv, { ip: job.quotaIp, anon: job.quotaAnon });
270|  }
271|}

