1|// Shared fakes for the upload route tests: scripted Meta/Jev clients, an
2|// in-memory Blob store, and small request builders. No network anywhere.
3|import { createMemoryKV } from "@/core/images";
4|import type { KV } from "@/core/types";
5|import type { RawSection } from "@/core/clean-types";
6|import type { JevClient, JevResult } from "../../pipeline/jev";
7|import type { MetaClient, MetaUsage } from "../../pipeline/meta";
8|import type { UploadEnv } from "./env";
