10|export { createMemoryKV };
11|export type { KV };
12|export { memoryStore, type MemoryStore } from "./memory";
13|
14|export function testEnv(over: Partial<UploadEnv> = {}): UploadEnv {
15|  return {
16|    upstashUrl: "https://upstash.test",
17|    upstashToken: "upstash-token",
18|    uploadsToken: "uploads-token",
19|    metaKey: "owner-meta-key",
20|    sessionSecret: "session-secret-for-tests-only",
21|    ipSalt: "ip-salt-for-tests",
22|    spendCapMicro: 10_000_000,
23|    ...over,
24|  };
