27|export interface MetaCall {
28|  system: string;
29|  user: string;
30|  schemaName: string;
31|}
32|
33|const USAGE = { promptTokens: 1000, cachedTokens: 100, completionTokens: 100 };
34|
35|export function scriptedMeta(
36|  respond: (call: MetaCall) => unknown,
37|  usage: { promptTokens: number; cachedTokens: number; completionTokens: number } = USAGE,
38|): MetaClient & { calls: MetaCall[] } {
39|  const calls: MetaCall[] = [];
40|  return {
41|    calls,
42|    model: "muse-spark-1.3-contributor",
43|    async completeJson(input: { system: string; user: string; schemaName: string; schema: Record<string, unknown> }): Promise<MetaUsage> {
44|      const call = { system: input.system, user: input.user, schemaName: input.schemaName };
45|      calls.push(call);
46|      return { data: respond(call), ...usage };
47|    },
48|  };
49|}
50|
51|const CALM_VECTOR = {
52|  calma: 0.8,
53|  alegria: 0.05,
54|  tristeza: 0,
55|  suspenso: 0.05,
56|  misterio: 0,
57|  aventura: 0.05,
58|  combate: 0,
59|  asombro: 0.05,
60|};
61|
62|// Answers judge, segment, override, and direct calls well enough for the
63|// happy path: one scene per part, calm everywhere.
64|export function helpfulMeta(): MetaClient & { calls: MetaCall[] } {
65|  return scriptedMeta((call) => {
66|    if (call.schemaName === "clean_judge") return { sections: [], headCut: 0, tailCut: 0 };
67|    if (call.schemaName === "chapter_scenes") {
68|      const m = /first start_n is (\d+), last end_n is (\d+)/.exec(call.user);
69|      const start = Number(m?.[1] ?? 1);
70|      const end = Number(m?.[2] ?? start);
71|      return {
72|        scenes: [{ start_n: start, end_n: end, title: "A scene", summary: "Things happen.", characters: ["Jo"] }],
73|      };
74|    }
75|    if (call.schemaName === "emotion_override") return { vector: CALM_VECTOR, reason: "Calm." };
76|    return { vector: CALM_VECTOR, intensity: 0.3, tempo: 0.2, reason: "Calm." };
77|  });
78|}
