80|export function scriptedJev(over: Partial<JevResult> = {}): JevClient & { calls: number } {
81|  const client = {
82|    calls: 0,
83|    model: "jev-1.14.0",
84|    async classify(): Promise<JevResult> {
85|      client.calls += 1;
86|      return {
87|        vector: { ...CALM_VECTOR, unknown: 0 },
88|        choice: "calma",
89|        confidence: 0.95,
90|        intensity: 0.3,
91|        intensity_confidence: 0.9,
92|        tempo: 0.2,
93|        tempo_confidence: 0.9,
94|        model: "jev-1.14.0",
95|        input_tokens: 500,
96|        output_tokens: 50,
97|        ...over,
98|      } as JevResult;
99|    },
100|  };
101|  return client;
102|}
