104|const WORDS = ["maple", "river", "quiet", "lantern", "meadow", "sparrow", "thunder", "window", "garden", "harbor"];
105|
106|export function section(id: string, label: string, paras: number, wordsPerPara: number): RawSection {
107|  const blocks = [];
108|  for (let p = 0; p < paras; p++) {
109|    const words = [];
110|    for (let w = 0; w < wordsPerPara; w++) words.push(WORDS[(p + w) % WORDS.length]);
111|    blocks.push({ text: words.join(" "), heading: false });
112|  }
113|  return { id, href: `${id}.xhtml`, linear: true, types: [], docTitle: null, navLabel: label, blocks };
114|}
