120|export function postRequest(
121|  url: string,
122|  body: unknown,
123|  headers: Record<string, string> = {},
124|): Request {
125|  return new Request(url, {
126|    method: "POST",
127|    headers: { "content-type": "application/json", ...headers },
128|    body: typeof body === "string" ? body : JSON.stringify(body),
129|  });
