132|// Merges every Set-Cookie pair into one Cookie header for the next call.
133|export function cookiesFrom(res: Response, prev = ""): string {
134|  const found = typeof res.headers.getSetCookie === "function" ? res.headers.getSetCookie() : [];
135|  const pairs = found.map((c) => c.split(";")[0] as string);
136|  const jar = new Map<string, string>();
137|  for (const part of [...prev.split(";"), ...pairs]) {
138|    const eq = part.indexOf("=");
139|    if (eq > 0) jar.set(part.slice(0, eq).trim(), part.slice(eq + 1).trim());
140|  }
141|  return [...jar.entries()].map(([k, v]) => `${k}=${v}`).join("; ");
142|}
