224|// The only money writer. The first caller folds actual-minus-reserved into
225|// both spend counters; every other terminal path is a no-op, so a retried
226|// finalize, a racing fail, and the stale cleanup can never double-adjust.
227|// Never throws; true when this call won the guard.
228|export async function settleSpendOnce(kv: KV, job: UploadJob, actualMicro: number): Promise<boolean> {
229|  let first = false;
230|  try {
231|    first = await kv.setNxEx(uploadRefundKey(job.id), "1", UPLOAD_JOB_TTL_SEC);
232|  } catch {
233|    return false;
234|  }
235|  if (!first || job.reservedMicro <= 0) return first;
236|  const delta = actualMicro - job.reservedMicro;
237|  if (delta !== 0) {
238|    try {
239|      await kv.incrBy(spendKey(), delta);
240|      await kv.incrBy(uploadDailySpendKey(job.day), delta);
241|    } catch {
242|      // Kept on Redis failure: conservative, like an abandoned job.
243|    }
244|  }
245|  return true;
