1|// In-memory UploadStore for tests and the e2e harness. No server-only
2|// import, so scripts can load it under plain tsx.
3|import type { UploadStore } from "./blob";
4|
5|export type MemoryStore = UploadStore & {
6|  files: Map<string, string>;
7|  writes: { path: string; json: string }[];
8|};
9|
10|export function memoryStore(times: Map<string, number> = new Map()): MemoryStore {
11|  const files = new Map<string, string>();
12|  const writes: { path: string; json: string }[] = [];
13|  return {
14|    files,
15|    writes,
16|    async saveJson(path: string, json: string): Promise<void> {
17|      files.set(path, json);
18|      writes.push({ path, json });
19|    },
20|    async readText(path: string): Promise<string | null> {
21|      return files.get(path) ?? null;
22|    },
23|    async remove(path: string): Promise<void> {
24|      files.delete(path);
25|    },
26|    async listAll(prefix: string): Promise<{ pathname: string; uploadedAt: number }[]> {
27|      return [...files.keys()]
28|        .filter((k) => k.startsWith(prefix))
29|        .map((pathname) => ({ pathname, uploadedAt: times.get(pathname) ?? Date.now() }));
30|    },
31|  };
32|}

