5|// Per-person quota, counted by hashed IP and by the anonymous
6|// cookie, whichever runs out first. Day keys are UTC dates.
7|export const CHAT_QUOTA_TTL_SEC = 48 * 3600;
8|
9|export interface DualKeys {
10|  ip: string;
11|  anon: string;
12|}
13|
14|export async function takeDualQuota(
15|  kv: KV,
16|  keys: DualKeys,
17|  opts: { limit: number; ttlSec: number },
18|): Promise<{ ok: true; ipCount: number; anonCount: number } | { ok: false }> {
19|  let ipTaken = false;
20|  let anonTaken = false;
21|  try {
22|    const ipCount = await kv.incr(keys.ip);
23|    ipTaken = true;
24|    await kv.expire(keys.ip, opts.ttlSec);
25|    const anonCount = await kv.incr(keys.anon);
26|    anonTaken = true;
27|    await kv.expire(keys.anon, opts.ttlSec);
28|    if (ipCount > opts.limit || anonCount > opts.limit) {
29|      // Compensating decrs are best effort: a Redis failure here must
30|      // neither throw nor leak the caller's counts, so each stands alone.
31|      try {
32|        await kv.decr(keys.ip);
33|      } catch {
34|        // The increment already landed; the TTL bounds the damage.
35|      }
36|      try {
37|        await kv.decr(keys.anon);
38|      } catch {
39|        // The increment already landed; the TTL bounds the damage.
40|      }
41|      return { ok: false };
42|    }
43|    return { ok: true, ipCount, anonCount };
44|  } catch (e) {
45|    // A Redis failure between increments gives back what landed, so a
46|    // timeout never leaks quota. Best effort, then the caller maps it.
47|    if (anonTaken) {
48|      try {
49|        await kv.decr(keys.anon);
50|      } catch {
51|        // The increment already landed; the TTL bounds the damage.
52|      }
53|    }
54|    if (ipTaken) {
55|      try {
56|        await kv.decr(keys.ip);
57|      } catch {
58|        // The increment already landed; the TTL bounds the damage.
59|      }
60|    }
61|    throw e;
62|  }
63|}
64|
65|// Best effort: a Redis failure here must never become a client 500.
66|export async function refundDualQuota(kv: KV, keys: DualKeys): Promise<void> {
67|  try {
68|    await kv.decr(keys.ip);
69|    await kv.decr(keys.anon);
70|  } catch {
71|    // Redis down: nothing reserved server-side to retry against.
72|  }
73|}
74|
75|// Free uploaded-book processing: two books per person per UTC day,
76|// counted on hashed IP and the anon cookie, whichever hits first.
77|export const FREE_BOOKS_PER_PERSON = 2;
78|// BYOK uploads spend the reader's key, but creates still need a per-person
79|// cap so a bot cannot farm infinite jobs; same dual counting, own prefix.
80|export const BYOK_UPLOADS_PER_PERSON = 10;
81|export const BOOK_QUOTA_TTL_SEC = 48 * 3600;
82|
83|export function bookQuotaKeys(args: { day: string; ipHash: string; anonId: string; prefix?: string }): DualKeys {
84|  const prefix = args.prefix ?? "books:quota";
85|  return {
86|    ip: `${prefix}:ip:${args.day}:${args.ipHash}`,
87|    anon: `${prefix}:anon:${args.day}:${args.anonId}`,
88|  };
89|}
90|
91|export function bookQuotaKeysFor(args: {
92|  day: string;
93|  ip: string;
94|  salt: string;
95|  anonId: string;
96|  prefix?: string;
97|}): DualKeys {
98|  return bookQuotaKeys({
99|    day: args.day,
100|    ipHash: hashIp(ipBucket(args.ip, args.anonId), args.salt),
101|    anonId: args.anonId,
102|    prefix: args.prefix,
103|  });
104|}
105|
106|// Thin wrapper so the book hook shares the never-throw compensation.
107|export async function checkBookQuota(
108|  kv: KV,
109|  keys: DualKeys,
110|): Promise<{ ok: true } | { ok: false }> {
111|  const taken = await takeDualQuota(kv, keys, {
112|    limit: FREE_BOOKS_PER_PERSON,
113|    ttlSec: BOOK_QUOTA_TTL_SEC,
114|  });
115|  return taken.ok ? { ok: true } : { ok: false };
116|}
117|
118|export async function refundBookQuota(kv: KV, keys: DualKeys): Promise<void> {
119|  await refundDualQuota(kv, keys);
